/**
 * Exploded Commit block: one content write, taken apart layer by layer.
 *
 * An isometric exploded view (exploded-commit.svg, generated by
 * tools/exploded-commit/build.mjs) beside an ordered list of authored labels.
 * Each label is joined to its layer by a leader line; hovering or focusing a
 * label outlines its layer in brass, and hovering a layer lights its label.
 *
 * Authoring contract (DA), up to 5 rows, top to bottom, each [label | description]:
 *
 *   | Exploded Commit |                                          |
 *   | --------------- | ---------------------------------------- |
 *   | Document        | The JCR node you wrote                   |
 *   | Signature       | Sealed by your wallet                    |
 *   | Settlement      | Paid on Ethereum (sepolia mode)          |
 *   | Ordering        | Sequenced by a three-validator cluster   |
 *   | Storage         | Applied by each validator to its own Oak TAR segments |
 *
 * Rows map to layers by position: 1 document card, 2 signature plate,
 * 3 settlement coin, 4 validator tiles, 5 segment slab. A missing row or cell
 * falls back to the default above. Authored rows and cells are moved intact
 * into the list (never rebuilt), so DA Canvas keeps editing them; rows past
 * the fifth stay in the list after the five layers.
 *
 * The figure is decorative (aria-hidden); the ordered list is the content.
 * In DA Canvas (html[quick-edit]) and under prefers-reduced-motion the figure
 * renders exploded and still, and in Canvas no interaction is wired.
 */
import { isAuthoring } from '../../scripts/scripts.js';

const DEFAULTS = [
  ['Document', 'The JCR node you wrote'],
  ['Signature', 'Sealed by your wallet'],
  ['Settlement', 'Paid on Ethereum (sepolia mode)'],
  ['Ordering', 'Sequenced by a three-validator cluster'],
  ['Storage', 'Applied by each validator to its own Oak TAR segments'],
];

const FIGURE_URL = new URL('./exploded-commit.svg', import.meta.url);

function cell(role, text) {
  const div = document.createElement('div');
  div.className = `exploded-commit-${role}`;
  div.textContent = text;
  return div;
}

/** Classify an authored row in place, filling only the cells that are missing. */
function adoptRow(row, index) {
  const [label, description] = [...row.children];
  const [defaultLabel, defaultDescription] = DEFAULTS[index] || [];
  if (label) label.classList.add('exploded-commit-label');
  else if (defaultLabel) row.append(cell('label', defaultLabel));
  if (description) description.classList.add('exploded-commit-description');
  else if (defaultDescription) row.append(cell('description', defaultDescription));
  row.classList.add('exploded-commit-row');
  return row;
}

function defaultRow(index) {
  const row = document.createElement('div');
  row.className = 'exploded-commit-row';
  const [label, description] = DEFAULTS[index];
  row.append(cell('label', label), cell('description', description));
  return row;
}

async function loadFigure() {
  try {
    const response = await fetch(FIGURE_URL);
    if (!response.ok) return null;
    const parsed = new DOMParser().parseFromString(await response.text(), 'image/svg+xml');
    const svg = parsed.documentElement;
    if (svg.nodeName !== 'svg') return null;
    return document.importNode(svg, true);
  } catch {
    return null;
  }
}

function setActive(block, layer) {
  block.querySelectorAll('[data-layer]').forEach((el) => {
    el.classList.toggle('is-active', el.dataset.layer === layer);
  });
  block.classList.toggle('has-active', Boolean(layer));
}

function wireHighlight(block) {
  const pick = (event) => event.target.closest?.('[data-layer]')?.dataset.layer || null;
  block.addEventListener('pointerover', (event) => setActive(block, pick(event)));
  block.addEventListener('pointerleave', () => setActive(block, null));
  block.addEventListener('focusin', (event) => setActive(block, pick(event)));
  block.addEventListener('focusout', (event) => {
    if (!block.contains(event.relatedTarget)) setActive(block, null);
  });
}

/** Ease the layers apart once, the first time the figure is seen. */
function explodeOnView(block, figure) {
  block.classList.add('is-assembled');
  const observer = new IntersectionObserver((entries) => {
    if (!entries.some((entry) => entry.isIntersecting)) return;
    observer.disconnect();
    requestAnimationFrame(() => requestAnimationFrame(() => block.classList.remove('is-assembled')));
  }, { threshold: 0.2 });
  observer.observe(figure);
}

/**
 * loads and decorates the block
 * @param {Element} block The block element
 */
export default async function decorate(block) {
  const authoring = isAuthoring();
  const rows = [...block.children];
  const list = document.createElement('ol');
  list.className = 'exploded-commit-list';

  const count = Math.max(DEFAULTS.length, rows.length);
  for (let index = 0; index < count; index += 1) {
    const item = document.createElement('li');
    item.className = 'exploded-commit-item';
    if (index < DEFAULTS.length) {
      item.dataset.layer = String(index + 1);
      if (!authoring) item.tabIndex = 0;
    } else {
      item.classList.add('is-extra');
    }
    item.append(rows[index] ? adoptRow(rows[index], index) : defaultRow(index));
    list.append(item);
  }

  const figure = document.createElement('div');
  figure.className = 'exploded-commit-figure';
  const svg = await loadFigure();
  if (svg) {
    figure.append(svg);
    const [, , , height] = (svg.getAttribute('viewBox') || '').split(/\s+/).map(Number);
    const anchors = (svg.dataset.anchors || '').split(/\s+/).map(Number);
    [...list.children].forEach((item, index) => {
      const y = anchors[index];
      if (!height || !Number.isFinite(y) || item.classList.contains('is-extra')) return;
      item.style.setProperty('--ec-anchor', `${((y / height) * 100).toFixed(2)}%`);
      const marker = document.createElement('span');
      marker.className = 'exploded-commit-marker';
      marker.setAttribute('aria-hidden', 'true');
      marker.textContent = String(index + 1).padStart(2, '0');
      marker.style.setProperty('--ec-anchor', `${((y / height) * 100).toFixed(2)}%`);
      figure.append(marker);
    });
    block.classList.add('has-figure');
  }

  block.replaceChildren(figure, list);

  if (authoring || !svg) return;
  wireHighlight(block);
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) explodeOnView(block, figure);
}
